from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
DEMO='https://xanderzhou2022.github.io/AccessRoute_small_demo/'
CODE='https://github.com/XanderZhou2022/AccessRoute_small_demo'
SITE='https://xanderzhou2022.github.io/AccessRoute/'
ARROW='<span class="arrow" aria-hidden="true">↗</span>'
pages=[('index.html','Home'),('journey.html','Journey'),('technology.html','Technology'),('validation.html','Validation'),('resources.html','Resources')]
brand='<svg class="brand-mark" viewBox="0 0 30 36" aria-hidden="true"><path d="M3 30V10a6 6 0 0 1 12 0v16a6 6 0 0 0 12 0V6"/></svg><span>AccessRoute<small> HK</small></span>'

def layout(file,title,description,content):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==file else '')+f'>{label}</a>' for url,label in pages)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)} · AccessRoute HK</title><meta name="description" content="{escape(description)}">
<meta name="theme-color" content="#173c35"><meta property="og:title" content="{escape(title)} · AccessRoute HK"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><meta property="og:image" content="{SITE}assets/route-concept.png"><meta property="og:url" content="{SITE}{'' if file=='index.html' else file}">
<link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/site.css?v=2"><script src="assets/site.js" defer></script></head>
<body id="top"><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="AccessRoute HK home">{brand}</a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button><nav id="site-nav" class="nav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main">{content}</main>
<footer class="footer"><div class="wrap"><div class="footer-top"><div><a class="brand" href="index.html">{brand}</a><p>Accessible first and last mile navigation.<br>Built for Hong Kong’s vertical city.</p></div><div class="footer-links"><a href="journey.html">The journey</a><a href="technology.html">The technology</a><a href="resources.html">Downloads</a><a href="{CODE}" target="_blank" rel="noopener">GitHub ↗</a></div></div><div class="footer-bottom"><span>HumanRoute · Team 1022</span><span>Hong Kong · 2026</span><a class="backtop" href="#top">Back to top ↑</a></div></div></footer></body></html>'''

def head(label,title,description):
    return f'<div class="wrap"><header class="page-head"><div class="breadcrumb"><a href="index.html">Home</a><span>/</span>{label}</div><span class="eyebrow">{label}</span><h1>{title}</h1><p class="lead">{description}</p></header></div>'

def resource(href,title,description,format,download=False):
    return f'<a class="resource-row" href="{href}"'+(' download' if download else '')+f'><div><h3>{title}</h3><p>{description}</p></div><span class="format">{format}</span>{ARROW}</a>'

home='''<div class="wrap"><section class="hero"><div class="hero-copy"><span class="eyebrow">Hong Kong, floor by floor</span><h1>Accessible routes.<br>Personal journeys.</h1><p class="lead">Routes shaped by your mobility needs, from the first lift to the final street crossing.</p><div class="links"><a class="button" href="journey.html">Explore the journey <span class="arrow" aria-hidden="true">↗</span></a><a class="text-link" href="resources.html">Project materials</a></div></div><figure class="hero-visual"><span class="visual-label">The AccessRoute experience</span><img class="screen" src="assets/screens/overview.png" width="390" height="844" alt="AccessRoute phone interface with a route overview, 3D map and walking stages"><span class="side-note">PLANNED AROUND YOUR NEEDS</span><figcaption class="visual-caption">From PopCorn 2 to Kowloon Tong</figcaption></figure></section><div class="hero-meta"><div><strong>12</strong> mapped scenes</div><div><strong>4</strong> AI workflows</div><div><strong>3</strong> journey stages</div></div></div>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Explore AccessRoute</span><h2>Explore the project.</h2></div><p>Follow a journey, look inside the system, or go straight to the project materials.</p></div><div class="directory">'''
for n,url,title,desc in [
 ('01','journey.html','The journey','See the interface, route choices and Kowloon Tong field journey.'),
 ('02','technology.html','The technology','How map data, AI workflows and route planning work together.'),
 ('03','validation.html','The evidence','Explore scene coverage, regression checks and route recovery.'),
 ('04','resources.html','The materials','Product manual, presentation, video and technical references.')]:
    home+=f'<a class="directory-item" href="{url}"><span class="num">{n}</span><div><h3>{title}</h3><p>{desc}</p></div>{ARROW}</a>'
home+='''</div></div></section><section class="feature-strip"><div class="wrap feature-inner"><div><span class="eyebrow">A route in Kowloon Tong</span><h2>The Kowloon Tong<br>route.</h2><p>At the footbridge, the journey can continue outdoors or through Festival Walk. Stair access, lift availability and shelter preferences shape the choice.</p><a class="text-link" href="journey.html#kowloon-tong">Follow the route ↗</a></div><img class="feature-photo" src="assets/kowloon-tong.png" alt="Kowloon Tong Station entrance from the team's field journey video" loading="lazy"></div></section>'''
(OUT/'index.html').write_text(layout('index.html','Accessible routes. Personal journeys.','AccessRoute HK combines mobility needs, floor-aware maps and confirmed observations into a continuous journey.',home))

journey=head('Journey','The journey,<br>floor by floor.','Choose your needs, follow each stage and update the remaining route when the situation changes.')
journey+='''<section class="section"><div class="wrap split"><div><span class="eyebrow">The route</span><h2>PopCorn 2<br>to Kowloon Tong.</h2><p>A complete journey combines walking at each end with a rail stage between them.</p><div class="links"><a class="button" href="'''+DEMO+'''" target="_blank" rel="noopener">Open the web demo ↗</a></div></div><div class="stage-list"><article class="stage"><h3>Origin walking</h3><p>Navigate PopCorn 2’s corridors and lifts to the transport connection. Personal mobility settings determine the available path.</p></article><article class="stage"><h3>The rail connection</h3><p>Follow the station sequence from Tseung Kwan O through Tiu Keng Leng to Kowloon Tong.</p></article><article class="stage"><h3>Destination walking</h3><p>Leave Kowloon Tong through Exit F. Continue towards the Cornwall Street public interchange using the outdoor path or a route through Festival Walk.</p></article></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">On the phone</span><h2>Clear at every step.</h2></div><p>The route overview, current instruction and arrival screen share the same journey state.</p></div><div class="screen-gallery"><figure><img src="assets/screens/overview.png" alt="Phone route overview showing journey summary and map" width="390" height="844" loading="lazy"><figcaption>01 <span>Review the journey</span></figcaption></figure><figure><img src="assets/screens/navigation.png" alt="Phone navigation screen showing the current step, map and assistance actions" width="390" height="844" loading="lazy"><figcaption>02 <span>Follow the current step</span></figcaption></figure><figure><img src="assets/screens/arrival.png" alt="Phone arrival screen showing the destination and replan action" width="390" height="844" loading="lazy"><figcaption>03 <span>Reach the destination</span></figcaption></figure></div></div></section>
<section class="section" id="kowloon-tong"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The field journey</span><h2>Walking Kowloon Tong.</h2></div><p>The team’s field video follows the route from the station through the surrounding pedestrian connections.</p></div><div class="video-section"><video controls playsinline preload="metadata" poster="assets/kowloon-tong.png" aria-label="Kowloon Tong field journey video"><source src="assets/video/product-demo.mp4" type="video/mp4"><a href="assets/video/product-demo.mp4">Download the field journey video</a></video><div class="video-caption"><p>Kowloon Tong Station, Festival Walk and the surrounding paths. 33 seconds.</p><a class="inline-link" href="assets/video/product-demo.mp4" download>Download video</a></div></div><div class="route-options"><article class="route-option"><h3>Outdoor path</h3><p>The footbridge connects to the outdoor stairs and paths towards Cornwall Street.</p></article><article class="route-option"><h3>Festival Walk north exit</h3><p>The route enters the mall, uses a public lift and continues through the G-level north exit.</p></article><article class="route-option"><h3>CityU tunnel connection</h3><p>The LG1 connection links through the CityU side. The graph retains the stairs on the street connection.</p></article></div></div></section>
<section class="section"><div class="wrap split"><div><span class="eyebrow">When a route changes</span><h2>Continue from<br>where you are.</h2></div><div class="stage-list"><article class="stage"><h3>Report a blocked facility</h3><p>Submit a photo or description. Review the affected facility or path, then confirm the report to update the route.</p></article><article class="stage"><h3>Find your location</h3><p>Photograph a visible landmark. The system compares it with nearby map candidates and asks you to confirm the position.</p></article><article class="stage"><h3>Follow the remaining journey</h3><p>The planner starts at the updated position and keeps the completed stages. Read the next step or play its Cantonese instruction.</p></article></div></div></section>'''
(OUT/'journey.html').write_text(layout('journey.html','The journey','Follow the AccessRoute phone interface, Kowloon Tong field route, photo confirmation and facility-closure recovery.',journey))

tech=head('Technology','Maps, models<br>and routing.','A shared routing engine connects floor graphs, mobility preferences and confirmed observations.')
tech+='''<section class="section"><div class="wrap"><span class="eyebrow">System architecture</span><h2>Routing architecture.</h2><div class="architecture-band"><div><h3>Scene data</h3><p>Official floor geometry, pedestrian paths and field anchors.</p></div><span class="arrow" aria-hidden="true">→</span><div><h3>Routing context</h3><p>Mobility constraints, preferences, weather and active events.</p></div><span class="arrow" aria-hidden="true">→</span><div><h3>Journey steps</h3><p>Dijkstra routes become floor, lift, bridge and outdoor instructions.</p></div></div><p class="source-note">React and TypeScript on the phone. Express on the server. Shared domain contracts connect them.</p></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Four AI workflows</span><h2>Four AI workflows.</h2></div><p>Qwen text and vision models work with the loaded map. Each workflow returns structured results.</p></div><div class="tech-list"><article><span class="eyebrow">01 · Preferences</span><h3>Understand the traveller.</h3><p>Voice or text becomes mobility settings: stair access, lift requirements, shelter preference and instruction format. The user reviews the settings before applying them.</p><code>Language → preferences → route planning</code></article><article><span class="eyebrow">02 · Obstacle reporting</span><h3>Locate the affected facility.</h3><p>Vision extracts the visible barrier and signage. Map retrieval selects nearby facilities or paths. A confirmed match creates a timed event for rerouting.</p><code>Photo → facility match → event overlay</code></article><article><span class="eyebrow">03 · Visual localisation</span><h3>Match what the camera sees.</h3><p>The system reads names, floor signs and visible objects, then compares them with nearby map records. A confirmed candidate becomes the new route origin.</p><code>Photo → map candidates → current position</code></article><article><span class="eyebrow">04 · Cantonese guidance</span><h3>Explain the current step.</h3><p>Confirmed route facts provide the distance, floor, facility and action. The guidance workflow turns those facts into a short Cantonese instruction for browser speech.</p><code>Route facts → Cantonese text → playback</code></article></div></div></section>
<section class="section"><div class="wrap split"><div><span class="eyebrow">Photo matching</span><h2>Photo-to-map<br>matching.</h2><p>Separating image observation from map matching keeps every candidate tied to an existing node or facility.</p></div><div><div class="stage-list"><article class="stage"><h3>Read the image</h3><p>The vision role extracts text, floor labels, landmarks and obstacle evidence.</p></article><article class="stage"><h3>Retrieve map candidates</h3><p>Floor and position narrow the search. Name and OCR similarity rank nearby records.</p></article><article class="stage"><h3>Compare the evidence</h3><p>The matching role checks the observation against the retrieved records. Scores combine identity, evidence, proximity and route context.</p></article><article class="stage"><h3>Confirm and apply</h3><p>The user confirms the candidate. The server validates its map ID and current journey context before updating the remaining route.</p></article></div></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Routing and state</span><h2>Session coordination.</h2></div><p>The phone and control console use the same server session.</p></div><div class="tech-list"><article><h3>Constraints before preferences</h3><p>Mobility policies remove unavailable edges. The planner then evaluates distance, exposure, effort or time. Sheltered and indoor objectives compare exposure before secondary cost.</p></article><article><h3>Events over a stable graph</h3><p>Facility closures and path reports form an event overlay. The base graph stays unchanged, and event validity determines which restrictions apply.</p></article><article><h3>Shared phone and console</h3><p>HTTP commands update the journey. Server-sent events deliver versioned state snapshots to both screens, including after reconnection.</p></article><article><h3>Current-position rerouting</h3><p>Completed steps remain in the journey. Confirmed location changes and active events replace the remaining route from the current anchor.</p></article></div></div></section>
<section class="section"><div class="wrap"><span class="eyebrow">Model and service interfaces</span><div class="table-scroll"><table class="data-table"><thead><tr><th>Component</th><th>Implementation</th><th>Role</th></tr></thead><tbody><tr><td>Language and vision</td><td>Qwen-compatible API</td><td>Structured preference, observation, matching and guidance output.</td></tr><tr><td>Speech</td><td>Browser speech services</td><td>Voice input and device Cantonese playback.</td></tr><tr><td>Weather</td><td>Hong Kong Observatory API</td><td>District observations, warnings and cached weather context.</td></tr><tr><td>Maps</td><td>Lands Department and MTR data</td><td>Floor geometry, pedestrian networks and station information.</td></tr></tbody></table></div><p class="source-note">Text and vision model names are selected in the backend configuration. <a class="inline-link" href="resources.html#references">Data and service references</a></p></div></section>'''
(OUT/'technology.html').write_text(layout('technology.html','The technology','Read the routing architecture, four AI workflows, map evidence matching and shared journey state behind AccessRoute.',tech))

report=json.loads((OUT/'downloads/regression-report.json').read_text()) if (OUT/'downloads/regression-report.json').exists() else None
test_count=report['testsPassed'] if report else '—'
file_count=report['testFiles'] if report else '—'
validation=head('Validation','Testing and<br>scene coverage.','Routing, map contracts and journey recovery are checked against the same data used by the product.')
validation+=f'''<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Regression record · 18 October 2026</span><h2>Regression results.</h2></div><p>Automated regression checks cover the routing core, workflows, HTTP interfaces and shared session state.</p></div><div class="metric-row"><div class="metric"><strong>{test_count}</strong><span>tests passed</span></div><div class="metric"><strong>{file_count}</strong><span>test files</span></div><div class="metric"><strong>12</strong><span>registered scenes</span></div></div><a class="text-link" href="downloads/regression-report.json">Read the test record ↗</a></div></section>'''
validation+='''<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">What the checks cover</span><h2>Test coverage.</h2></div><p>These are software regression checks of defined routes, events and state transitions.</p></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Area</th><th>Check</th><th>Expected behaviour</th></tr></thead><tbody><tr><td>Accessibility policies</td><td>Stairs, escalators, slope and unknown attributes</td><td>Hard constraints exclude the affected graph edges.</td></tr><tr><td>Weather and objectives</td><td>Distance, shelter, indoor routing, effort and time</td><td>The selected objective changes route cost and preference ordering.</td></tr><tr><td>Facility events</td><td>Closure, restoration and alternate routes</td><td>The remaining route changes or returns a clear no-route state.</td></tr><tr><td>Photo workflows</td><td>Observation, map IDs and candidate confirmation</td><td>Only valid candidates from the current map can be applied.</td></tr><tr><td>Journey sessions</td><td>Command versions, reconnection, reset and persistence</td><td>The phone and console retain a consistent state.</td></tr><tr><td>Scene contracts</td><td>Manifest, graph, floor and facility references</td><td>Each scene loads through the same validated schema.</td></tr></tbody></table></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Scene coverage</span><h2>The scene catalogue.</h2></div><p>The catalogue combines malls, government buildings, markets and community facilities.</p></div><div class="scene-grid">'''
for scene in json.loads((OUT/'assets/scenes.json').read_text()):
    validation+=f'<article class="scene"><h3>{escape(scene["name"])}</h3><span>{scene["floors"]} mapped levels</span></article>'
validation+='''</div><p class="source-note">Eleven scenes use official floor and unit geometry. Kowloon Tong / Festival Walk uses a layered pedestrian network. <a class="inline-link" href="downloads/scene-catalogue.json">Download the scene catalogue</a></p></div></section>
<section class="section"><div class="wrap split"><div><span class="eyebrow">Route recovery</span><h2>Route recovery<br>examples.</h2></div><div class="stage-list"><article class="stage"><h3>Lift A closes</h3><p>A confirmed closure targets Lift A. The event policy removes its affected edges, and the planner selects a remaining path through Lift B when that path is available.</p></article><article class="stage"><h3>A landmark resets the origin</h3><p>Confirming the A-1 Bakery candidate moves the start anchor to the nearby LG1 public passage. The route is recalculated from that node.</p></article></div></div></section>
<section class="section"><div class="wrap split"><div><span class="eyebrow">Next measurements</span><h2>Field evaluation.</h2></div><div><p class="lead">A field evaluation can record journey completion, time to recover after a simulated closure, labelled-photo match accuracy and task-level model latency and cost.</p><p class="muted">The Kowloon Tong route provides a concrete setting for comparing these measures across mobility profiles.</p><a class="text-link" href="journey.html#kowloon-tong">See the field journey ↗</a></div></div></section>'''
(OUT/'validation.html').write_text(layout('validation.html','Validation','Explore regression checks, the twelve-scene catalogue and route-recovery examples.',validation))

resources=head('Resources','Project materials<br>and references.','Read the manual, download the presentation or explore the source and supporting materials.')
resources+='<section class="section"><div class="wrap split"><div><div class="download-panel"><span class="eyebrow">Start here</span><h3>AccessRoute product manual</h3><p>An English guide to the product, with complete journeys, interface screenshots and technical detail.</p><a class="button" href="downloads/product-manual.pdf" target="_blank" rel="noopener">Read the manual ↗</a></div></div><div><div class="resource-group"><h2>Project materials</h2>'
resources+=resource('downloads/product-manual.pdf','Product manual','English walkthroughs, screenshots and architecture.','PDF · 2.2 MB')
resources+=resource('downloads/presentation.pptx','Project presentation','Technical pages, team presentation and embedded video.','PPTX · 8.5 MB',True)
resources+=resource('assets/video/product-demo.mp4','Kowloon Tong field journey','Station, mall and pedestrian connections.','MP4 · 33 sec',True)
resources+=resource('assets/video/route-concept.mp4','Route concept animation','An animated indoor route with lift alternatives.','MP4',True)
resources+='</div><div class="resource-group"><h2>Code and verification</h2>'
resources+=resource(CODE,'Navigation source repository','Application code, scene data and setup instructions.','GITHUB')
resources+=resource(DEMO,'Browser demo','Explore the published navigation interface.','WEB')
resources+=resource('downloads/regression-report.json','Regression record','The dated test summary, file-level results and covered cases.','JSON')
resources+=resource('downloads/scene-catalogue.json','Scene catalogue','Names, levels and identifiers for the twelve scenes.','JSON')
resources+=resource('downloads/cantonese-speech-patch.zip','Cantonese speech patch','Voice-loading fixes and tests for the teammate interface.','ZIP',True)
resources+='</div></div></div></section><section class="section" id="references"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Data and services</span><h2>Technical references.</h2></div><p>Official sources for the geography, transit and weather information used by AccessRoute.</p></div>'
for href,title,desc in [
 ('https://portal.csdi.gov.hk/csdi-webpage/apidoc/3d-indoor-map-api','3D Indoor Building Map','Lands Department floor, unit, opening and amenity data.'),
 ('https://portal.csdi.gov.hk/csdi-webpage/apidoc/3d-indoor-mtr-station-map','3D Indoor MTR Station Map','Station levels and indoor features.'),
 ('https://portal.csdi.gov.hk/csdi-webpage/apidoc/3d-pedestrian-route-search','3D Pedestrian Route Search','Indoor and outdoor pedestrian route geometry.'),
 ('https://data.gov.hk/en-data/dataset/mtr-data-routes-fares-barrier-free-facilities','MTR routes and barrier-free facilities','Station sequence and facility datasets.'),
 ('https://www.hko.gov.hk/en/abouthko/opendata_intro.htm','Hong Kong Observatory open data','Current weather observations and warning summaries.'),
 ('https://www.alibabacloud.com/help/en/model-studio/','Qwen API documentation','Language and vision model service interfaces.')]:
    resources+=resource(href,title,desc,'REFERENCE')
resources+='''<p class="source-note">Map from Lands Department © Government of the Hong Kong Special Administrative Region. Map data retains its original <a class="inline-link" href="https://portal.csdi.gov.hk/csdi-webpage/terms-and-conditions">source terms</a>.</p></div></section>
<section class="section"><div class="wrap split"><div><span class="eyebrow">Running the product</span><h2>Open the full<br>navigation service.</h2></div><div><p class="muted">The navigation repository contains the phone interface, Express service and shared route engine. Install Node.js 22.12 or later, then follow its README.</p><pre class="code">npm ci\nnpm run build\nnpm start</pre><p class="source-note">Open the local service on port 8787. Configure the backend model credentials for live Qwen workflows. This project website hosts documents, images and videos.</p></div></div></section>'''
(OUT/'resources.html').write_text(layout('resources.html','Resources','Download the English manual, project presentation, videos, test record and scene catalogue.',resources))

(OUT/'404.html').write_text(layout('404.html','Page not found','Return to the AccessRoute project website.','<div class="wrap not-found"><span class="eyebrow">404</span><h1>Let’s find your way back.</h1><p>The project’s main sections are one click away.</p><a class="button" href="'+SITE+'">Return to AccessRoute ↗</a></div>'))
